    text += "\nUsage: executable completion <SHELL>\n\nFor more information, try '--help'.\n"
    raise CliError(text)


def help_unrecognized(arg, usage="top"):
    if usage == "completion":
        text = f"error: unrecognized subcommand '{arg}'\n\nUsage: executable completion <SHELL>\n\nFor more information, try '--help'.\n"
    elif usage == "help":
        text = f"error: unrecognized subcommand '{arg}'\n\nUsage: executable help [COMMAND]...\n\nFor more information, try '--help'.\n"
    else:
