    raise CliError(text)


def value_required(opt_long, metav=""):
    extra = ""
    if opt_long == "--encoding":
        extra = "\n  [possible values: utf8-lossy, utf8]"
    text = f"error: a value is required for '{opt_long} {metav}' but none was supplied{extra}\n\nFor more information, try '--help'.\n"
    raise CliError(text)


def invalid_float(opt_long, val):
    text = f"error: invalid value '{val}' for '{opt_long} <{'HSCALE' if opt_long == '--horizontal-scale' else 'VSCALE'}>': invalid float literal\n\nFor more information, try '--help'.\n"
    raise CliError(text)


def invalid_padding(val):
    text = f"error: invalid value '{val}' for '--padding <PADDING>': invalid digit found in string\n\nFor more information, try '--help'.\n"
    raise CliError(text)


def invalid_encoding(val):
    text = f"error: invalid value '{val}' for '--encoding <ENCODING>'\n  [possible values: utf8-lossy, utf8]\n"
    if val == "utf-8":
        text += "\n  tip: a similar value exists: 'utf8'\n"
    text += "\nFor more information, try '--help'.\n"
    raise CliError(text)


def parse_float(val, opt_long):
    try:
        # Rust's parser accepts NaN/inf/+2/1e1, case-insensitively for these names.
        return float(val)
    except Exception:
        invalid_float(opt_long, val)


def parse_padding_val(val):
