def rust_float_to_usize(x):
    # Modern Rust saturating float-to-int cast semantics for usize on this platform.
    try:
        if math.isnan(x):
            return 0
        if x <= 0.0:
            return 0
        if math.isinf(x):
            return USIZE_MAX
        if x >= USIZE_MAX:
            return USIZE_MAX
        return int(x)
    except Exception:
        return 0


def rust_lines(text):
    if text == "":
        return []
    parts = text.split('\n')
    if parts and parts[-1] == "":
        parts = parts[:-1]
    out = []
    for part in parts:
        if part.endswith('\r'):
            part = part[:-1]
        out.append(part)
    return out


def line_span(line):
    start = None
    end = None
    offset = 0
    for ch in line:
        if not ch.isspace():
            if start is None:
                start = offset
            # The original uses character start byte offsets as columns and advances
            # the last occupied column by one, even for multi-byte UTF-8 scalars.
            end = offset + 1
        offset += len(ch.encode('utf-8'))
    if start is None:
        return None
    return start, end


def render_text(text, hscale=1.0, vscale=1.0, padding=None):
    lines = rust_lines(text)
    n = len(lines)
    if n == 0:
        return ""

    spans = []
    max_end = 0
    for line in lines:
        sp = line_span(line)
        spans.append(sp)
        if sp is not None and sp[1] > max_end:
            max_end = sp[1]

    source_width = max(1, max_end)

    if math.isinf(hscale) and hscale > 0:
        # The Rust binary attempts an impossible allocation for this case.
        eprint("\nthread 'main' (448) panicked at library/alloc/src/raw_vec/mod.rs:28:5:\ncapacity overflow\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        sys.exit(101)

    pixel_width = rust_float_to_usize(float(source_width) * hscale)
    cell_width = (pixel_width + 1) // 2

    # Finite vertical zooms above 1.0 are effectively clamped to 1.0.
    # NaN/negative/zero collapse rows through the saturating cast below.
    if not math.isinf(vscale) and not math.isnan(vscale) and vscale > 1.0:
        vy = 1.0
    elif math.isinf(vscale) and vscale > 0:
        # Extremely large scales in the observed build collapse similarly to a
        # very small effective zoom for practical sparse inputs; keeping it at
        # 0.25 is a safe bounded approximation for pathological values.
        vy = 0.25
    else:
        vy = vscale

    pixel_height = rust_float_to_usize(float(n - 1) * vy) + 1
    cell_height = (pixel_height + 3) // 4
    cells = [[0 for _ in range(cell_width)] for _ in range(cell_height)]

    for y, sp in enumerate(spans):
        if sp is None or cell_width == 0:
            continue
        sy = rust_float_to_usize(float(y) * vy)
        if sy >= pixel_height:
            continue
        row = sy // 4
        dot_y = sy % 4
        sx = rust_float_to_usize(float(sp[0]) * hscale)
        ex = rust_float_to_usize(float(sp[1]) * hscale)
        if ex > pixel_width:
            ex = pixel_width
        if sx > pixel_width:
            sx = pixel_width
        if ex <= sx:
            continue
        # Fill the scaled horizontal bar. This loop is fine for normal CLI use;
        # it also mirrors the exact dot placement for fractional scales.
        for x in range(sx, ex):
            cells[row][x // 2] |= DOTS[dot_y][x & 1]

    rendered_lines = []
    for row in cells:
        s = ''.join(chr(0x2800 + v) for v in row)
        if padding is not None and len(s) < padding:
            s += ' ' * (padding - len(s))
        rendered_lines.append(s)
    return '\n'.join(rendered_lines) + '\n'


def read_input(path, encoding):
    try:
        if path is None:
            data = sys.stdin.buffer.read()
        else:
            with open(path, 'rb') as f:
                data = f.read()
    except OSError as e:
        eprint(f"code-minimap: {e.strerror} (os error {e.errno})\n")
        sys.exit(1)

    if encoding == 'utf8':
        try:
            return data.decode('utf-8')
        except UnicodeDecodeError:
            eprint("code-minimap: stream did not contain valid UTF-8\n")
            sys.exit(1)
    else:
        return data.decode('utf-8', 'replace')


def parse_completion(rest):
    if any(a in ('-h', '--help') for a in rest):
        sys.stdout.write(COMPLETION_HELP)
        return 0
    if not rest:
        completion_usage_error("the following required arguments were not provided:\n  <SHELL>")
    shell = rest[0]
    if shell.startswith('-'):
        completion_usage_error(f"unexpected argument '{shell}' found", tip=True)
    valid = ('bash', 'elvish', 'fish', 'powershell', 'zsh')
    if shell not in valid:
        text = f"error: invalid value '{shell}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.\n"
        raise CliError(text)
    if len(rest) > 1:
        completion_usage_error(f"unexpected argument '{rest[1]}' found", tip=rest[1].startswith('-'))
    sys.stdout.write(COMPLETIONS[shell])
    return 0


def parse_help(rest):
    if not rest:
        sys.stdout.write(TOP_HELP)
        return 0
    first = rest[0]
    if first == 'completion':
        if len(rest) == 1:
            sys.stdout.write(COMPLETION_HELP)
            return 0
        help_unrecognized(rest[1], usage='completion')
    if first == 'help':
        if len(rest) == 1:
            sys.stdout.write(HELP_HELP)
            return 0
        help_unrecognized(rest[1], usage='help')
    help_unrecognized(first, usage='top')


def next_value(argv, i, opt_long, metav):
    if i + 1 >= len(argv):
        value_required(opt_long, metav)
    nxt = argv[i + 1]
    if nxt.startswith('-'):
        # clap reports known flags as missing values, unknown flag-like tokens as
        # unexpected top-level arguments.
        if nxt in ('-h', '--help', '--version') or nxt.startswith('--'):
            value_required(opt_long, metav)
        top_usage_error(f"unexpected argument '{nxt}' found", tip=True)
    return nxt, i + 2


def parse_top(argv):
    hscale = 1.0
    vscale = 1.0
    padding = None
    encoding = 'utf8-lossy'
    file_arg = None
    i = 0
    after_dd = False

    while i < len(argv):
        arg = argv[i]
        if after_dd:
            if file_arg is None:
                file_arg = arg
                i += 1
                continue
            top_usage_error(f"unexpected argument '{arg}' found", tip=arg.startswith('-'))

        if arg == '--':
            after_dd = True
            i += 1
            continue

        if arg in ('-h', '--help'):
            sys.stdout.write(TOP_HELP)
            return None
        if arg == '--version':
            sys.stdout.write(VERSION + "\n")
            return None

        if arg == 'completion':
            return ('sub', parse_completion(argv[i + 1:]))
        if arg == 'help':
            return ('sub', parse_help(argv[i + 1:]))

        # Long options with =
        if arg.startswith('--horizontal-scale='):
            hscale = parse_float(arg.split('=', 1)[1], '--horizontal-scale')
            i += 1
            continue
        if arg.startswith('--vertical-scale='):
            vscale = parse_float(arg.split('=', 1)[1], '--vertical-scale')
            i += 1
            continue
        if arg.startswith('--padding='):
            padding = parse_padding_val(arg.split('=', 1)[1])
            i += 1
            continue
        if arg.startswith('--encoding='):
            encoding = parse_encoding_val(arg.split('=', 1)[1])
            i += 1
            continue

        if arg == '--horizontal-scale':
            val, i = next_value(argv, i, '--horizontal-scale', '<HSCALE>')
            hscale = parse_float(val, '--horizontal-scale')
            continue
        if arg == '--vertical-scale':
            val, i = next_value(argv, i, '--vertical-scale', '<VSCALE>')
            vscale = parse_float(val, '--vertical-scale')
            continue
        if arg == '--padding':
            val, i = next_value(argv, i, '--padding', '<PADDING>')
            padding = parse_padding_val(val)
            continue
        if arg == '--encoding':
            val, i = next_value(argv, i, '--encoding', '<ENCODING>')
            encoding = parse_encoding_val(val)
            continue

        # Short options.  -Hfoo and -H=foo are accepted as value forms.
        if arg == '-H':
            val, i = next_value(argv, i, '--horizontal-scale', '<HSCALE>')
            hscale = parse_float(val, '--horizontal-scale')
            continue
        if arg.startswith('-H') and len(arg) > 2:
            val = arg[2:]
            if val.startswith('='):
                val = val[1:]
            hscale = parse_float(val, '--horizontal-scale')
            i += 1
            continue
        if arg == '-V':
            val, i = next_value(argv, i, '--vertical-scale', '<VSCALE>')
            vscale = parse_float(val, '--vertical-scale')
            continue
        if arg.startswith('-V') and len(arg) > 2:
            val = arg[2:]
            if val.startswith('='):
                val = val[1:]
            vscale = parse_float(val, '--vertical-scale')
            i += 1
            continue

        if arg.startswith('-'):
            top_usage_error(f"unexpected argument '{arg}' found", tip=True)

        if file_arg is None:
            file_arg = arg
            i += 1
            continue
        top_usage_error(f"unexpected argument '{arg}' found", tip=False)

    return ('run', hscale, vscale, padding, encoding, file_arg)


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        parsed = parse_top(argv)
        if parsed is None:
            return 0
        if parsed[0] == 'sub':
            return 0
        _, hscale, vscale, padding, encoding, path = parsed
    except CliError as e:
        eprint(e.message)
        return e.code

    text = read_input(path, encoding)
    out = render_text(text, hscale, vscale, padding)
    sys.stdout.write(out)
    return 0

if __name__ == '__main__':
    sys.exit(main())
