    pixel_width = rust_float_to_usize(float(source_width) * hscale)
    cell_width = (pixel_width + 1) // 2

    # Finite vertical zooms above 1.0 are effectively clamped to 1.0.
    # NaN/negative/zero collapse rows through the saturating cast below.
    if not math.isinf(vscale) and not math.isnan(vscale) and vscale > 1.0:
        vy = 1.0
    elif math.isinf(vscale) and vscale > 0:
